sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_randomSeed;
uniform float amzp_useField;
uniform float amzp_lowpassType;
uniform float amzp_inputLuma;
uniform float amzp_chromaLowpassIn;
uniform float amzp_compositeSharpen;
uniform float amzp_chromaGain;
uniform float amzp_subcarrier;
uniform float amzp_noiseEnabled;
uniform float amzp_noiseIntensity;
uniform float amzp_noiseFrequency;
uniform float amzp_noiseDetail;
uniform float amzp_snow;
uniform float amzp_snowAnisotropy;
uniform float amzp_scanlinePhaseShift;
uniform float amzp_scanlinePhaseOffset;
uniform float amzp_chromaDemod;
uniform float amzp_lumaSmear;
uniform float amzp_headEnabled;
uniform float amzp_headHeight;
uniform float amzp_headOffset;
uniform float amzp_headHShift;
uniform float amzp_midLineEnabled;
uniform float amzp_midLinePosition;
uniform float amzp_midLineJitter;
uniform float amzp_trackingHeight;
uniform float amzp_trackingWaveIntensity;
uniform float amzp_trackingSnow;
uniform float amzp_trackingNoise;
uniform float amzp_intensity;
uniform float amzp_quality;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float th1(float x) { x = clamp(x, -15.0, 15.0); float e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float3 th3(float3 x) { x = clamp(x, -15.0, 15.0); float3 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float4 th4(float4 x) { x = clamp(x, -15.0, 15.0); float4 e = exp(2.0 * x); return (e - 1.0) / (e + 1.0); }
    float2x2 rot2(float a) { float c = cos(a), s = sin(a); return float2x2(c, -s, s, c); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float3 unpre(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float hsh(float2 p) { float3 p3 = fract(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
    float h21(float2 p) { float3 p3 = fract(float3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }
    float3 rgb2yiq(float3 c) { return float3(dot(c, float3(0.299, 0.587, 0.114)), dot(c, float3(0.595716, -0.274453, -0.321263)), dot(c, float3(0.211456, -0.522591, 0.311135))); }
    float3 yiq2rgb(float3 c) { return float3(c.x + 0.9563 * c.y + 0.6210 * c.z, c.x - 0.2721 * c.y - 0.6474 * c.z, c.x - 1.1070 * c.y + 1.7046 * c.z); }
    float3 sYIQ(float2 uv) { return rgb2yiq(unpre(layerClamp(uv))); }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 uv = amzLayerNorm();
        float2 res = W / max(pxs(), 0.0001);
        float line = floor(uv.y * res.y);
        float seed = amzp_randomSeed * 0.137 + 1.0;
        float t = TT();
        float invW = 1.0 / res.x, invH = 1.0 / res.y;
        float lfb = line + 0.5;
        float xshift = 0.0;
        if ((amzp_headEnabled>0.5)) {
            if (lfb > amzp_headOffset && lfb <= amzp_headOffset + amzp_headHeight) {
                float f = (lfb - amzp_headOffset) / max(amzp_headHeight, 1.0);
                float sh = amzp_headHShift * invW * (1.0 - f);
                if ((amzp_midLineEnabled>0.5)) {
                    float amzLocal_pos = clamp(amzp_midLinePosition + (h21(float2(line, seed)) - 0.5) * amzp_midLineJitter, 0.0, 1.0);
                    if (uv.x > amzLocal_pos) xshift += sh;
                } else xshift += sh;
            }
        }
        float tn = 0.0;
        if (lfb <= amzp_trackingHeight && amzp_trackingHeight > 0.5) {
            float f = 1.0 - lfb / max(amzp_trackingHeight, 1.0);
            tn = f;
            xshift += (sin(uv.y * res.y * 0.6 + t * 9.0) + (h21(float2(line, seed + 7.0)) - 0.5)) * amzp_trackingWaveIntensity * invW * f;
        }
        float2 suv = float2(uv.x + xshift, uv.y);
        float xpix = suv.x * res.x;
        float sub = amzp_subcarrier;
        float phaseDeg = float(int(amzp_scanlinePhaseShift)) * 90.0;
        float linePh = radians(phaseDeg) * mod(line + amzp_scanlinePhaseOffset, 4.0) + t * 0.6;
        float demErr = (h21(float2(line, seed + 3.0)) - 0.5) * 0.7;
        float K = 2.0 + floor(amzp_quality + 0.5);
        float sY = 0.0, sI = 0.0, sQ = 0.0, ws = 0.0;
        for (int k = -8; k <= 8; k++) {
            float fk = float(k);
            if (abs(fk) > K) continue;
            float3 s = sYIQ(suv + float2(fk * invW, 0.0));
            float xp = xpix + fk;
            float enc = sub * xp + linePh, dem = enc + demErr;
            float comp = s.x + s.y * cos(enc) + s.z * sin(enc);
            float w = exp(-fk * fk * 0.16);
            sY += comp * w; sI += comp * cos(dem) * w; sQ += comp * sin(dem) * w; ws += w;
        }
        float3 yiq = float3(sY / ws, 2.0 * sI / ws * amzp_chromaGain, 2.0 * sQ / ws * amzp_chromaGain);
        if (int(amzp_chromaDemod) == 0) {
            float3 a = sYIQ(suv + float2(invW, 0.0)), b = sYIQ(suv - float2(invW, 0.0));
            yiq.yz = (yiq.yz + (a.yz + b.yz) * amzp_chromaGain) / 3.0;
        } else if (int(amzp_chromaDemod) >= 2) {
            float3 up = sYIQ(suv + float2(0.0, invH));
            float3 up2 = int(amzp_chromaDemod) == 3 ? sYIQ(suv + float2(0.0, 2.0 * invH)) : up;
            yiq.yz = mix(yiq.yz, (up.yz + up2.yz) * 0.5 * amzp_chromaGain, 0.5);
        }
        float cpx = int(amzp_chromaLowpassIn) == 1 ? 1.5 : (int(amzp_chromaLowpassIn) == 2 ? 2.5 : 0.0);
        if (int(amzp_lowpassType) == 1) cpx *= 0.7; else if (int(amzp_lowpassType) == 2) cpx = 0.0;
        if (cpx > 0.01) {
            float si = 0.0, sq = 0.0, sw2 = 0.0;
            for (int k = -6; k <= 6; k++) {
                float fk = float(k);
                float3 s = sYIQ(suv + float2(fk * invW, 0.0));
                float xp = xpix + fk;
                float enc = sub * xp + linePh, dem = enc + demErr;
                float comp = s.x + s.y * cos(enc) + s.z * sin(enc);
                float w = exp(-fk * fk * 0.35 / (cpx * cpx));
                si += comp * cos(dem) * w; sq += comp * sin(dem) * w; sw2 += w;
            }
            yiq.yz = float2(2.0 * si / sw2, 2.0 * sq / sw2) * amzp_chromaGain;
        }
        float yb = 0.0;
        for (int k = -2; k <= 2; k++) yb += sYIQ(suv + float2(float(k) * invW, 0.0)).x;
        yb /= 5.0;
        if (int(amzp_inputLuma) == 2) yiq.x = yb;
        else if (int(amzp_inputLuma) == 1) yiq.x += (yiq.x - yb) * 0.6;
        if ((amzp_noiseEnabled>0.5)) {
            float nfreq = mix(2.0, 40.0, amzp_noiseFrequency);
            float n = h21(float2(line * 0.5 + floor(t * 60.0), seed)) - 0.5;
            float amp = 0.5;
            for (int o = 0; o < 5; o++) {
                if (float(o) >= amzp_noiseDetail - 0.5) break;
                float fo = float(o) + 1.0;
                n += (h21(float2(xpix * nfreq * 0.02 * fo + line, seed + fo)) - 0.5) * amp;
                amp *= 0.6;
            }
            yiq.x += n * amzp_noiseIntensity * 0.6;
        }
        if (amzp_lumaSmear > 0.001) {
            float yl = sYIQ(suv - float2(amzp_lumaSmear * 10.0 * invW, 0.0)).x;
            yiq.x = mix(yiq.x, max(yiq.x, yl * 0.95), amzp_lumaSmear);
        }
        if (abs(amzp_compositeSharpen) > 0.001) yiq.x += (yiq.x - yb) * amzp_compositeSharpen;
        if (int(amzp_useField) != 3 && int(amzp_useField) != 2) {
            float par = mod(line + floor(t * 50.0) + (int(amzp_useField) == 1 ? 1.0 : 0.0), 2.0);
            yiq.x *= 1.0 - 0.10 * par;
        }
        if (amzp_snow > 0.001) {
            float ax = floor(xpix / mix(1.0, 6.0, amzp_snowAnisotropy));
            if (h21(float2(ax + floor(t * 120.0) * 1.3, line * 1.7 + seed)) > 1.0 - clamp(amzp_snow * 0.01, 0.0, 1.0)) yiq = float3(0.9, 0.0, 0.0);
        }
        if (tn > 0.001) {
            float st = h21(float2(xpix + floor(t * 120.0) * 1.9, line + seed + 11.0));
            yiq.x = mix(yiq.x, st, amzp_trackingSnow * tn) + (st - 0.5) * amzp_trackingNoise * tn;
        }
        float3 oc = clamp(yiq2rgb(yiq), 0.0, 1.0);
        float3 org = unpre(orig);
        float a = max(orig.a, layerClamp(suv).a * step(0.0001, abs(xshift)));
        float4 R = float4(mix(org, oc, amzp_intensity) * a, a);
        amzOutput = R;
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
